solution:
CODES = {400: "bad_request", 401: "unauthorized", 403: "forbidden", 404: "not_found", 422: "validation_error"}


def error_response(status, message, details=None):
    return {"error": {"status": status, "code": CODES.get(status, "error"), "message": message, "details": details or []}}

